def _write_out(text):
    stream = sys.stdout
    buf = getattr(stream, "buffer", None)
    if buf is not None:
        buf.write(text.encode("utf-8"))
        buf.flush()
    else:
        stream.write(text)
        stream.flush()


def _write_err(text):
    stream = sys.stderr
    try:
        buf = getattr(stream, "buffer", None)
        if buf is not None:
            buf.write(text.encode("utf-8", "replace"))
            buf.flush()
        else:
            stream.write(text)
            stream.flush()
    except (OSError, ValueError):
        pass


def _silence_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(ctx, code):
    text = "".join(ctx.out)
    if not text:
        return code
    try:
        _write_out(text)
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except OSError as exc:
        _silence_stdout()
        _write_err("tallybook: cannot write output: %s\n" % (exc.strerror or exc))
        return 1
    return code


def _fail(err_lines):
    _write_err("".join(line + "\n" for line in err_lines))


