        existing = self._existing(ids)
    result = _csvimport.import_csv(text, profile, rules, existing)
    outcome = ImportOutcome([], list(result.duplicates), list(result.errors))
    if result.errors:
        return outcome
    dup_counts = {}
    for tx in result.duplicates:
        key = self._base_key(tx, account)
        dup_counts[key] = dup_counts.get(key, 0) + 1
    seen = {}
    keys = []
    for tx in result.transactions:
        base = self._base_key(tx, account)
        seen[base] = seen.get(base, 0) + 1
        keys.append("%s|%d" % (base, dup_counts.get(base, 0) + seen[base]))
    bulk = self.add_transactions(result.transactions, keys)
    outcome.added = bulk.added
    for index in bulk.skipped:
        outcome.duplicates.append(result.transactions[index])
    return outcome

